import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosSeparator } from "../../index";

/**
 * Vue's Separator: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Separator`; Default written by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const meta: Meta<Args> = {
  title: "Vue/Core/Layout/Separator",
  component: KozmosSeparator,
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosSeparator, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

/** React's Default, as its render draws it: a rule under a heading, and two between links. */
export const Default: Story = {
  render: () => ({
    components: { KozmosSeparator },
    template: `
      <div class="space-y-1">
        <h4 class="text-sm font-medium leading-none">Radix Primitives</h4>
        <p class="text-sm text-muted-foreground">
          An open-source UI component library.
        </p>
        <KozmosSeparator class="my-4" />
        <div class="flex h-5 items-center space-x-4 text-sm">
          <div>Blog</div>
          <KozmosSeparator orientation="vertical" />
          <div>Docs</div>
          <KozmosSeparator orientation="vertical" />
          <div>Source</div>
        </div>
      </div>
    `,
  }),
};
